<div data-applicant-field><div class="field-label">Desa / kelurahan <span class="required-mark">*</span></div><div class="ajax-village" data-url="<?= site_url('api/wilayah/desa') ?>" data-district="district-register"><input type="hidden" name="village_id" value="<?= $selected_village ? (int) $selected_village->id : '' ?>"><input class="ajax-village-input" type="search" role="combobox" aria-autocomplete="list" aria-expanded="false" autocomplete="off" placeholder="Cari desa / kelurahan" value="<?= e($selected_village ? $selected_village->village_name : '') ?>" required><div class="ajax-village-results" role="listbox" hidden></div></div></div>
